import random


def strategy(history, rng):
    n = len(history)

    if n == 0:
        return 'C'

    # Count outcomes
    cc = cd = dc = dd = 0
    for mine, opp in history:
        if mine == 'C' and opp == 'C':
            cc += 1
        elif mine == 'C' and opp == 'D':
            cd += 1
        elif mine == 'D' and opp == 'C':
            dc += 1
        else:
            dd += 1

    # Last few moves
    last_opp = history[-1][1]
    last_mine = history[-1][0]

    # Detect very cooperative or very hostile opponents
    coop_ratio = (cc + dc) / float(n)
    defect_ratio = (cd + dd) / float(n)

    # If opponent is mostly cooperative, cooperate but occasionally test for exploitation
    if coop_ratio >= 0.85:
        # Small noise every ~20 rounds to detect if they start defecting
        if n % 17 == 0 and rng.random() < 0.15:
            return 'D'
        return 'C'

    # If opponent is mostly defecting, mostly defect but don't get stuck in DD forever
    if defect_ratio >= 0.65:
        # Occasionally cooperate to see if they respond
        if n % 11 == 0 and rng.random() < 0.1:
            return 'C'
        return 'D'

    # Tit-for-tat with forgiveness and anti-exploitation
    if last_opp == 'C':
        # Opponent cooperated: usually cooperate back
        return 'C'
    else:
        # Opponent defected last turn
        # Check if they defected after we cooperated (exploitation signal)
        if last_mine == 'C':
            # Punish immediately but with some chance to forgive
            recent_defections = 0
            lookback = min(5, n)
            for i in range(n - lookback, n):
                if history[i][1] == 'D':
                    recent_defections += 1
            if recent_defections >= 3:
                return 'D'
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        else:
            # We both defected: try to break the cycle
            both_defected_run = 0
            for i in range(n - 1, -1, -1):
                if history[i][0] == 'D' and history[i][1] == 'D':
                    both_defected_run += 1
                else:
                    break
            if both_defected_run >= 2:
                # Try cooperating to reset relationship
                if rng.random() < 0.4:
                    return 'C'
                return 'D'
            return 'D'
